export const forgotPassword = async (
  req: Request,
  res: Response,
): Promise<Response> => {
  try {
    const { email } = req.body;
    await forgotPasswordService(email);
    // Return a generic success to prevent email enumeration
    const resultant: ApiResponse<null> = {
      success: true,
      statusCode: 200,
      message: 'If the email exists, a password reset code has been sent.',
      data: null,
    };
    return res.status(200).json(resultant);
  } catch (error) {
    logContext.function = 'forgotPassword';
    logger.error(logContext, 'Error in forgotPassword controller', { error });
    throw error;
  }
};

export const getMe = async (
  req: AuthenticatedRequest,
  res: Response,
): Promise<Response> => {
  try {
    const { user } = req;
    const profile = await getCurrentUserProfile(user!.userId);
    if (!profile) {
      throw new EntityNotFoundError({ message: 'User not found', code: 'ENTITY_NOT_FOUND' });
    }

    const resultant: ApiResponse<typeof profile> = {
      success: true,
      statusCode: 200,
      message: 'User fetched successfully',
      data: profile,
    };
    return res.status(200).json(resultant);
  } catch (error) {
    logContext.function = 'getMe';
    logger.error(logContext, 'Error in getMe controller', { error });
    throw error;
  }
};